import json
import os
import tempfile

import requests

NEON_SITE_URL = "https://data.neonscience.org/api/v0/sites/ABBY"
SITE_CODE = "ABBY"
DATASET_ID = "DP1.00094.001"
RADIUS_M = 2000


def locate_site(folder: str, output1: str) -> None:
    faasr_log(f"Querying NEON site endpoint {NEON_SITE_URL}")
    try:
        resp = requests.get(NEON_SITE_URL, timeout=30)
        resp.raise_for_status()
        payload = resp.json()
    except Exception as e:
        faasr_log(f"ERROR: failed to retrieve NEON site record for {SITE_CODE}: {e}")
        raise RuntimeError(f"Failed to retrieve NEON site record for {SITE_CODE}: {e}") from e

    data = payload.get("data") if isinstance(payload, dict) else None
    if not data or data.get("siteCode") != SITE_CODE:
        msg = f"NEON API returned no site record for {SITE_CODE}"
        faasr_log(f"ERROR: {msg}")
        raise RuntimeError(msg)

    lat = data.get("siteLatitude")
    lon = data.get("siteLongitude")
    if lat is None or lon is None:
        msg = f"NEON site record for {SITE_CODE} lacks latitude/longitude"
        faasr_log(f"ERROR: {msg}")
        raise RuntimeError(msg)
    lat = float(lat)
    lon = float(lon)
    if not (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0):
        msg = f"NEON site coordinates out of range: lat={lat}, lon={lon}"
        faasr_log(f"ERROR: {msg}")
        raise RuntimeError(msg)

    products = data.get("dataProducts") or []
    product = next((p for p in products if p.get("dataProductCode") == DATASET_ID), None)
    if product is None:
        msg = f"NEON site {SITE_CODE} does not list data product {DATASET_ID}"
        faasr_log(f"ERROR: {msg}")
        raise RuntimeError(msg)

    metadata = {
        "site_code": SITE_CODE,
        "site_name": data.get("siteDescription") or data.get("siteName") or "",
        "latitude": lat,
        "longitude": lon,
        "radius_m": RADIUS_M,
        "dataset_id": DATASET_ID,
        "state": data.get("stateCode"),
        "domain": data.get("domainCode"),
        "available_months": sorted(product.get("availableMonths") or []),
        "source_url": NEON_SITE_URL,
    }

    tmpdir = tempfile.mkdtemp()
    local_path = os.path.join(tmpdir, "site_metadata.json")
    with open(local_path, "w") as f:
        json.dump(metadata, f, indent=2)

    faasr_put_file(local_file=local_path, remote_folder=folder, remote_file=output1)
    faasr_log(
        f"Site {SITE_CODE} ({metadata['site_name']}): lat={lat}, lon={lon}, "
        f"radius_m={RADIUS_M}, {len(metadata['available_months'])} months of {DATASET_ID}"
    )
